// FIXED: Process dynamic metrics with correct n8n OpenAI node handling
const results = [];

for (const item of items) {
  try {
    // Parse AI response - handle different OpenAI node output structures
    let aiResponse;

    // PRIORITY 1: n8n OpenAI node with jsonOutput=true
    // When jsonOutput is enabled, the parsed JSON is directly in item.json
    if (item.json && item.json.document_info && item.json.metrics_discovered) {
      aiResponse = item.json;
      console.log('✅ Using pre-parsed JSON from n8n OpenAI node (jsonOutput=true)');
    }
    // PRIORITY 2: Raw string response (manual parsing needed)
    else if (typeof item.json === 'string') {
      aiResponse = JSON.parse(item.json);
      console.log('✅ Parsed JSON from string response');
    }
    // PRIORITY 3: Chat completion format with message.content
    else if (item.json && item.json.message && item.json.message.content) {
      const content = item.json.message.content;

      // Handle OpenAI's response format - content might have markdown code blocks
      if (typeof content === 'string') {
        // Strip markdown code blocks if present (```json ... ``` or ``` ... ```)
        const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```/) || content.match(/```\s*([\s\S]*?)\s*```/);
        const cleanContent = jsonMatch ? jsonMatch[1].trim() : content.trim();

        try {
          aiResponse = JSON.parse(cleanContent);
          console.log('✅ Parsed JSON from message.content');
        } catch (parseError) {
          console.error('❌ JSON parse error:', parseError.message);
          console.error('Attempted to parse:', cleanContent.substring(0, 500));
          throw new Error(`Failed to parse AI response: ${parseError.message}`);
        }
      } else {
        aiResponse = content;
      }
    }
    // PRIORITY 4: Response wrapper format
    else if (item.json && item.json.response) {
      aiResponse = typeof item.json.response === 'string'
        ? JSON.parse(item.json.response)
        : item.json.response;
      console.log('✅ Parsed JSON from response wrapper');
    }
    // PRIORITY 5: Fallback - assume item.json is already correct
    else {
      aiResponse = item.json;
      console.log('⚠️  Using item.json as-is (fallback)');
    }

    console.log('Parsed AI response:', JSON.stringify(aiResponse, null, 2));

    // Extract document info
    const docInfo = aiResponse.document_info || {};
    const metrics = aiResponse.metrics_discovered || [];

    if (metrics.length === 0) {
      console.log('No metrics found in AI response');
      results.push({
        json: {
          entity_id: 'NO_METRICS',
          document_name: docInfo.document_name || 'Unknown',
          metric_name: 'no_data',
          value: 0,
          error: 'No metrics discovered',
          date_added: new Date().toISOString()
        }
      });
      continue; // Skip to next item
    }

    // Convert each metric to an EAV row for Google Sheets
    for (const metric of metrics) {
      const entityId = `${docInfo.company_name || 'Unknown'}_${metric.period || 'Unknown'}_${Date.now()}`;

      const sheetRow = {
        entity_id: entityId,
        document_name: docInfo.document_name || 'Unknown',
        company_name: docInfo.company_name || 'Unknown',
        metric_name: metric.standardized_name || metric.raw_name,
        raw_metric_name: metric.raw_name,
        value: metric.value || 0,
        unit: metric.unit || '',
        period: metric.period || '',
        confidence: metric.confidence || 0,
        category: metric.category || '',
        source_location: metric.source_location || '',
        extraction_context: metric.extraction_context || '',
        document_type: docInfo.document_type || '',
        date_added: new Date().toISOString()
      };

      results.push({ json: sheetRow });
      console.log(`Added row: ${metric.standardized_name} = ${metric.value} (${metric.period})`);
    }

  } catch (error) {
    console.error('Error processing AI response:', error);
    console.error('Error stack:', error.stack);

    // Try to log the problematic content for debugging
    try {
      if (item.json && item.json.message && item.json.message.content) {
        console.error('Problematic content preview:', item.json.message.content.substring(0, 1000));
      } else {
        console.error('Raw item structure:', JSON.stringify(item.json, null, 2).substring(0, 1000));
      }
    } catch (logError) {
      console.error('Could not log raw item');
    }

    results.push({
      json: {
        entity_id: 'ERROR',
        document_name: 'Processing Error',
        metric_name: 'error',
        value: 0,
        error: error.message,
        date_added: new Date().toISOString()
      }
    });
  }
}

console.log(`Successfully prepared ${results.length} metric rows for Google Sheets`);
return results;
